import { fireEvent, renderHook } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";

import { SHORTCUTS, shortcutLabel, useShortcuts, type ShortcutActionId } from "./shortcuts";

const TERMINAL_CHORD_CASES: readonly [string, ShortcutActionId, KeyboardEventInit][] = [
  ["new terminal tab", "tab.newTerminal", { key: "t", metaKey: true }],
  ["close active tab", "tab.close", { key: "w", metaKey: true }],
  ["next terminal tab", "tab.next", { key: "PageDown", ctrlKey: true }],
  ["previous terminal tab", "tab.previous", { key: "PageUp", ctrlKey: true }],
  ["split terminal right", "terminal.splitRight", { key: "d", metaKey: true }],
  ["split terminal down", "terminal.splitDown", { key: "d", metaKey: true, shiftKey: true }],
  ["close split view", "terminal.unsplit", { key: "d", metaKey: true, altKey: true }],
  [
    "close split view with the macOS Option glyph",
    "terminal.unsplit",
    { key: "∂", code: "KeyD", metaKey: true, altKey: true },
  ],
  ["open command palette", "commandPalette.open", { key: "k", metaKey: true }],
];

describe("shortcut registry", () => {
  it("contains the required frontend actions with platform-aware Mod labels", () => {
    expect(SHORTCUTS.map((shortcut) => shortcut.id)).toEqual([
      "tab.newTerminal",
      "tab.close",
      "tab.next",
      "tab.previous",
      "terminal.splitRight",
      "terminal.splitDown",
      "terminal.unsplit",
      "commandPalette.open",
    ]);
    expect(shortcutLabel("tab.newTerminal", true)).toBe("⌘T");
    expect(shortcutLabel("tab.newTerminal", false)).toBe("Ctrl+T");
    expect(shortcutLabel("terminal.splitDown", true)).toBe("⌘⇧D");
  });

  it("registers the app shortcut router in capture phase", () => {
    const addEventListener = vi.spyOn(window, "addEventListener");
    const { unmount } = renderHook(() => useShortcuts({ "tab.newTerminal": vi.fn() }, { isMac: true }));

    expect(addEventListener).toHaveBeenCalledWith("keydown", expect.any(Function), true);
    unmount();
    addEventListener.mockRestore();
  });

  it("dispatches only registered modifier chords and preserves ordinary xterm typing and Ctrl-C", () => {
    const handlers = {
      "tab.newTerminal": vi.fn(),
      "terminal.splitRight": vi.fn(),
      "commandPalette.open": vi.fn(),
    };
    renderHook(() => useShortcuts(handlers, { isMac: true }));
    const terminalHost = document.createElement("div");
    terminalHost.className = "terminal-host";
    const terminal = document.createElement("textarea");
    terminal.className = "xterm-helper-textarea";
    terminalHost.appendChild(terminal);
    document.body.appendChild(terminalHost);

    const ordinary = new KeyboardEvent("keydown", { key: "x", cancelable: true, bubbles: true });
    terminal.dispatchEvent(ordinary);
    expect(ordinary.defaultPrevented).toBe(false);

    const ctrlC = new KeyboardEvent("keydown", { key: "c", ctrlKey: true, cancelable: true, bubbles: true });
    terminal.dispatchEvent(ctrlC);
    expect(ctrlC.defaultPrevented).toBe(false);

    const split = new KeyboardEvent("keydown", { key: "d", metaKey: true, cancelable: true, bubbles: true });
    terminal.dispatchEvent(split);
    expect(split.defaultPrevented).toBe(true);
    expect(handlers["terminal.splitRight"]).toHaveBeenCalledOnce();

    terminalHost.remove();
  });

  it.each(TERMINAL_CHORD_CASES)("routes %s when xterm is focused", (_label, actionId, eventInit) => {
    const handlers = {
      "tab.newTerminal": vi.fn(),
      "tab.close": vi.fn(),
      "tab.next": vi.fn(),
      "tab.previous": vi.fn(),
      "terminal.splitRight": vi.fn(),
      "terminal.splitDown": vi.fn(),
      "terminal.unsplit": vi.fn(),
      "commandPalette.open": vi.fn(),
    };
    renderHook(() => useShortcuts(handlers, { isMac: true }));
    const terminalHost = document.createElement("div");
    terminalHost.className = "terminal-host";
    const terminal = document.createElement("textarea");
    terminalHost.appendChild(terminal);
    document.body.appendChild(terminalHost);

    const event = new KeyboardEvent("keydown", { bubbles: true, cancelable: true, ...eventInit });
    terminal.dispatchEvent(event);

    expect(event.defaultPrevented).toBe(true);
    expect(handlers[actionId]).toHaveBeenCalledOnce();
    terminalHost.remove();
  });

  it("does not steal typing shortcuts from editable fields except command palette", () => {
    const handlers = {
      "tab.newTerminal": vi.fn(),
      "commandPalette.open": vi.fn(),
    };
    renderHook(() => useShortcuts(handlers, { isMac: false }));
    const input = document.createElement("input");
    document.body.appendChild(input);

    fireEvent.keyDown(input, { key: "t", ctrlKey: true });
    expect(handlers["tab.newTerminal"]).not.toHaveBeenCalled();

    fireEvent.keyDown(input, { key: "k", ctrlKey: true });
    expect(handlers["commandPalette.open"]).toHaveBeenCalledOnce();
    input.remove();
  });
});

import { cleanup, fireEvent, render, screen, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const native = vi.hoisted(() => ({
  createWorktree: vi.fn(),
  getWorktreeStatus: vi.fn(),
  listProjectBranches: vi.fn(),
  registerProject: vi.fn(),
  signalTerminal: vi.fn(),
}));

const workspace = vi.hoisted(() => ({
  closeTab: vi.fn(),
  disableSplit: vi.fn(),
  enableSplit: vi.fn(),
  ensureTabForWorktree: vi.fn(),
  openTab: vi.fn(),
  refreshWorktrees: vi.fn(),
  rotateSplit: vi.fn(),
  syncWorktrees: vi.fn(),
}));

vi.mock("./lib/tauri", () => ({
  DEFAULT_WORKSPACE_ID: "default",
  createWorktree: native.createWorktree,
  getWorktreeStatus: native.getWorktreeStatus,
  listProjectBranches: native.listProjectBranches,
  registerProject: native.registerProject,
  signalTerminal: native.signalTerminal,
  toIpcError: (error: unknown) => error,
}));

vi.mock("./state/workspaceStore", () => ({
  useWorkspaceStore: () => ({
    state: {
      activeWorktreePath: null,
      layout: { primaryTabId: null, secondaryTabId: null, split: "none", tabs: [] },
      sessions: {},
      worktrees: [],
    },
    agents: [],
    activatePrimary: vi.fn(),
    closeTab: workspace.closeTab,
    disableSplit: workspace.disableSplit,
    enableSplit: workspace.enableSplit,
    ensureTabForWorktree: workspace.ensureTabForWorktree,
    openTab: workspace.openTab,
    rotateSplit: workspace.rotateSplit,
    syncWorktrees: workspace.syncWorktrees,
  }),
}));

vi.mock("./state/workspaceRuntime", () => ({
  useWorkspaceRuntime: () => ({
    refreshWorktrees: workspace.refreshWorktrees,
    reportRuntimeError: vi.fn(),
    runtimeError: null,
  }),
}));

vi.mock("./components/Sidebar", () => ({
  Sidebar: ({
    onAddProject,
    onCreateWorktree,
    projects = [],
  }: {
    onAddProject?: () => void;
    onCreateWorktree: () => void;
    projects?: Array<{ workspaceId: string }>;
  }) => (
    <div>
      <button type="button" onClick={() => onAddProject?.()}>
        Add project
      </button>
      <button type="button" onClick={onCreateWorktree}>
        Add worktree
      </button>
      {projects.map((project) => (
        <span key={project.workspaceId}>Project {project.workspaceId}</span>
      ))}
    </div>
  ),
}));

vi.mock("./components/CommandPalette", () => ({ CommandPalette: () => null }));
vi.mock("./components/SettingsDialog", () => ({ SettingsDialog: () => null }));
vi.mock("./components/TerminalSplitView", () => ({ TerminalSplitView: () => null }));
vi.mock("./components/WorktreeDeleteDialog", () => ({ WorktreeDeleteDialog: () => null }));
vi.mock("./components/WorkspaceHeader", () => ({ WorkspaceHeader: () => null }));

import { App } from "./App";

afterEach(cleanup);

describe("App project workspace flow", () => {
  beforeEach(() => {
    localStorage.clear();
    native.createWorktree.mockReset();
    native.getWorktreeStatus.mockReset();
    native.listProjectBranches.mockReset();
    native.registerProject.mockReset();
    native.signalTerminal.mockReset();
    workspace.ensureTabForWorktree.mockReset();
    workspace.refreshWorktrees.mockReset();
  });

  it("re-registers the active persisted project before refreshing its worktrees", async () => {
    const project = { workspaceId: "rorca", repoRoot: "/repos/rorca" };
    localStorage.setItem("rorca.projects", JSON.stringify([project]));
    localStorage.setItem("rorca.active-project", project.workspaceId);
    native.registerProject.mockResolvedValue(project);

    render(<App />);

    await waitFor(() =>
      expect(native.registerProject).toHaveBeenCalledWith({
        workspaceId: project.workspaceId,
        repoPath: project.repoRoot,
      }),
    );
    await waitFor(() => expect(workspace.refreshWorktrees).toHaveBeenCalledOnce());
  });

  it("opens a registered project's real branch-dropdown worktree flow", async () => {
    native.registerProject.mockResolvedValue({ workspaceId: "rorca", repoRoot: "/repos/rorca" });
    native.listProjectBranches.mockResolvedValue([{ name: "main", isCurrent: true }]);

    render(<App />);

    fireEvent.click(screen.getByRole("button", { name: "Add project" }));
    expect(screen.getByRole("form", { name: "Add Project" })).toBeInTheDocument();
    fireEvent.change(screen.getByRole("textbox", { name: "Workspace id" }), { target: { value: "rorca" } });
    fireEvent.change(screen.getByRole("textbox", { name: "Repository path" }), { target: { value: "/repos/rorca" } });
    fireEvent.click(screen.getByRole("button", { name: "Add Project" }));

    await waitFor(() => expect(screen.getByText("Project rorca")).toBeInTheDocument());
    fireEvent.click(screen.getByRole("button", { name: "Add worktree" }));

    expect(screen.getByRole("form", { name: "Add Worktree" })).toBeInTheDocument();
    await waitFor(() => expect(native.listProjectBranches).toHaveBeenCalledWith("rorca"));
    expect(screen.getByRole("combobox", { name: "Base branch" })).toBeInTheDocument();
  });
});

